import collections

class LFUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity

        # key -> [value, frequency]
        self.cache_map = {}

        # freq (int) -> set of keys with that exact current usage count.
        # Using a list for O(1) access by index is faster than dict.get
        self.freq_lists = collections.defaultdict(set)

    def get(self, key: int):
        if not cache := self.cache_map.get(key): 
            return -1

        value, freq = *cache,

        # Remove from current frequency list and update map to new state (freq+1) before adding back
        del self.freq_lists[freq].add(key)

