def natural_key(s):
    import re

    def convert(text: str) -> list:
        return [int(c) if c.isdigit() else c.lower()
                for c in re.split(r'(\d+)', text)]

    # The key is a tuple of the converted parts.
    # This ensures that strings starting with digits are comparable
    # to those not, as tuples compare element-wise (empty list vs non-empty).
    return convert(s)
