  return async function load(key) {
    if (!inflight.has(key)) {
      // Create a promise for this key and store in map.
      let entry;

      try {
        loaderPromise = Promise.resolve(loader.call(this, arguments));

        await (entry.loaderResult ??= { value: null });

         inflight.set(
          key,
