export function defineRoutes<T extends Record<string, string>>(routes: T) {
  return Object.fromEntries(
    Object.entries(routes).map(([name, path]) => [
      name,
      createRouteHandler(path),
    ])
  ) as unknown;
}

function extractParams(templatePath: string): { [key in keyof any]?: never } | Record<string, undefined> & {} {
  const paramNames = templatePath.match(/:(\w+)/g)?.map((match) => match.slice(1)) ?? [];

  return Object.fromEntries(
    Array(paramNames.length).fill(null as unknown)
      .reduce<{ [key: string]: never }>((acc): { [k in keyof any]?: undefined; }, () =>
        acc
      )
   ) || {};
}

function createRouteHandler(templatePath: string) {
  const paramRegex = /:(\w+)/g;

  if (!paramRegex.test(path)) return (params?.$1 ?? path);
}
